import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

async function Cards({ dataPromise }: { dataPromise: ReturnType<typeof getDashboardData> }) {
  const data = await dataPromise
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function Revenue({ dataPromise }: { dataPromise: ReturnType<typeof getDashboardData> }) {
  const data = await dataPromise
  return <RevenueChart revenue={data.revenue} />
}

async function Invoices({ dataPromise }: { dataPromise: ReturnType<typeof getDashboardData> }) {
  const data = await dataPromise
  return <LatestInvoices invoices={data.invoices} />
}

export default function Page() {
  const dataPromise = getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<div>Loading stats...</div>}>
        <Cards dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<div>Loading revenue...</div>}>
        <Revenue dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<div>Loading invoices...</div>}>
        <Invoices dataPromise={dataPromise} />
      </Suspense>
    </main>
  )
}

